import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    print("Zip entries:")
    for n in z.namelist():
        print(" ", n)
    workbook_xml = z.read("xl/workbook.xml")
    wb_root = ET.fromstring(workbook_xml)
    sheets = wb_root.findall(".//m:sheet", NS)
    print("\nSheets in workbook.xml:")
    for s in sheets:
        print(f"  name={s.get('name')!r} sheetId={s.get('sheetId')} rId={s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')}")

    rels_xml = z.read("xl/_rels/workbook.xml.rels")
    rels_root = ET.fromstring(rels_xml)
    rel_map = {}
    for rel in rels_root:
        rel_map[rel.get("Id")] = rel.get("Target")
    print("\nRelationships:")
    for k, v in rel_map.items():
        print(f"  {k} -> {v}")

    shared = {}
    if "xl/sharedStrings.xml" in z.namelist():
        ss_root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for i, si in enumerate(ss_root.findall("m:si", NS)):
            shared[i] = "".join(t.text or "" for t in si.iter()) 
    print("\nShared strings count:", len(shared))

    for s in sheets:
        rid = s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        print(f"\n=== Sheet {s.get('name')!r} -> {target} ===")
        sheet_root = ET.fromstring(z.read(target))
        for row in sheet_root.findall(".//m:sheetData/m:row", NS):
            rnum = row.get("r")
            vals = []
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                isel = c.find("m:is", NS)
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif t == "inlineStr" and isel is not None:
                    val = "".join(x.text or "" for x in isel.iter())
                elif t == "b" and v is not None:
                    val = v.text == "1"
                elif v is not None:
                    val = v.text
                else:
                    val = None
                vals.append(f"{ref}={val!r}")
            print(f"row {rnum}: " + " | ".join(vals))

