import zipfile
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
with zipfile.ZipFile("budget.xlsx") as z:
    root = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

def col_letter(ref):
    return "".join(ch for ch in ref if ch.isalpha())

expenses = []
income = []
for row in root.findall(".//m:sheetData/m:row", NS):
    cells = {}
    for c in row.findall("m:c", NS):
        v = c.find("m:v", NS)
        if v is not None:
            cells[col_letter(c.get("r"))] = v.text
    r = int(row.get("r"))
    if 11 <= r <= 22 and "C" in cells:
        expenses.append((r, cells["C"]))
    if 4 <= r <= 7 and "B" in cells:
        income.append((r, cells["B"]))

total = sum(float(v) for _, v in expenses)
print("Expense rows (row, amount):", expenses)
print(f"Total expenses: {total:.2f}")

from collections import defaultdict
cats = defaultdict(float)
catmap = {}
for row in root.findall(".//m:sheetData/m:row", NS):
    cells = {}
    for c in row.findall("m:c", NS):
        v = c.find("m:v", NS)
        if v is not None:
            cells[col_letter(c.get("r"))] = v.text
    r = int(row.get("r"))
    if 11 <= r <= 22 and "A" in cells and "C" in cells:
        cats[cells["A"]] += float(cells["C"])
print("By category:", dict(cats))

